 head_ops:{landing:'dashboard',menus:all.slice(0,10),scope:'Seluruh cabang',supervisor:true,opening:true,note:'Mengawasi operasional lintas cabang dan laporan riil. Pengaturan dan laporan non-riil tidak tersedia pada akses bawaan.'},
 ops_admin:{landing:'kasir',menus:['kasir','reservasi','transaksi','produk','gudang','pembelian','pengeluaran','member'],scope:'Cabang akun',supervisor:false,opening:true,note:'Mengelola operasional, produk dan pembelian. Memerlukan PIN pejabat berwenang untuk aksi otorisasi; tidak memiliki Ringkasan, Laporan, atau Pengaturan.'},
